using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using OpenAI;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");
var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(sp =>
    new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient());

builder.Services.AddSingleton<ResearchTools>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    instructions: """
        You are a research assistant. When given a topic, you:
        1. Search the web for relevant information using the search tool (perform multiple searches to cover different aspects).
        2. Take notes on key findings using the note-taking tool.
        3. After gathering enough information, produce a comprehensive summary of your findings.

        Always search for at least 2-3 different aspects of the topic before summarizing.
        Include sources in your final summary.
        """,
    tools:
    [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.AddNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ]);

Console.WriteLine("=== AI Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
Console.WriteLine();

while (true)
{
    Console.Write("> ");
    var topic = Console.ReadLine();

    if (string.IsNullOrWhiteSpace(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.WriteLine($"\nResearching: {topic}\n");

    researchTools.ClearNotes();

    var response = await agent.RunAsync(
        $"Research the following topic and provide a detailed summary: {topic}",
        session: null,
        options: new ChatClientAgentRunOptions
        {
            ChatOptions = new ChatOptions
            {
                Temperature = 0f,
                MaxOutputTokens = 2048,
            },
        });

    Console.WriteLine("\n--- Research Summary ---\n");
    Console.WriteLine(response.Text);
    Console.WriteLine("\n------------------------\n");
}

